html:
{%- set no_default_print_heading = 1 -%}
{%- from "templates/print_formats/standard_macros.html" import add_header -%}

<div class="main-container">
  {{ add_header(0, 1, doc, letter_head, no_letterhead, print_settings) }}

  {%- set heading_label = (
      "Draft Service Order" if doc.docstatus == 0 else
      "Cancelled Service Order" if doc.docstatus == 2 else
      "Service Order"
  ) -%}

  {%- set supplier_addr = frappe.get_all("Address", filters={"link_name": doc.supplier, "link_doctype": "Supplier"}, fields=["address_line1", "address_line2", "city", "country"], limit=1) -%}
  {%- set prepared_by_name = frappe.db.get_value("User", doc.prepared_by, "full_name") if doc.prepared_by else "" -%}

  <style>
  {%- set border_inset = 0 -%}
  {%- set content_inner_padding = 3 -%}

  html, body { margin:0; padding:0; height:100%; font-family: Arial, sans-serif; font-size: 13px; }

  .letter-head img,
  .letter-head .logo,
  .letter-head .logo img,
  .header-logo img,
  .company-logo img {
    max-width: 160px !important;
    max-height: 90px !important;
    width: auto !important;
    height: auto !important;
    object-fit: contain !important;
    display: inline-block !important;
  }

  .print-format {
    position:relative;
    background:transparent !important;
    margin:0 !important;
    padding:0;
    font-family: Arial, sans-serif;
    font-size: 13px;
  }

  .page-border {
    position:fixed;
    top:{{ border_inset }}mm;
    left:{{ border_inset }}mm;
    right:{{ border_inset }}mm;
    bottom:{{ border_inset }}mm;
    border:1px solid #000;
    z-index:0;
    pointer-events:none;
  }

  .main-container {
    position:relative;
    z-index:1;
    padding:{{ content_inner_padding }}mm;
    font-family: Arial, sans-serif;
    font-size: 13px;
  }

  .print-heading,
  .print-heading + div { display:none !important; }

  .heading-label {
    font-size:18px;
    font-weight:600;
    text-align:center;
    color:#222;
    margin-bottom:1px;
    letter-spacing:1px;
    text-transform:uppercase;
    font-family: Arial, sans-serif;
  }

  .section { margin-bottom:1px; }

  .section-title {
    font-size:13px;
    font-weight:600;
    border-bottom:1px solid #000;
    color:#000;
    margin-bottom:2px;
    padding-bottom:1px;
    font-family: Arial, sans-serif;
  }

  .letter-head { margin-bottom:2mm !important; }

  .info-table, .items-table, .summary-table { width:100%; border-collapse:collapse; }
  .info-table td {
    padding:2px 0;
    vertical-align:top;
    font-size: 13px;
    font-family: Arial, sans-serif;
  }

  .items-table th {
    background:#fff;
    color:#000;
    border-bottom:1px solid #000;
    padding:3px 4px;
    font-weight:700;
    font-size:13px;
    font-family: Arial, sans-serif;
  }

  .items-table td {
    padding:3px 4px;
    border-bottom:none;
    vertical-align:top;
    line-height:1.15;
    font-size:13px;
    font-family: Arial, sans-serif;
  }

  .summary-table td {
    padding:3px 4px;
    border-bottom:1px solid #f0f3f5;
    line-height:1.1;
    font-size:13px;
    font-family: Arial, sans-serif;
  }

  .rt { text-align:right; }
  .cn { text-align:center; }
  .grand-total td {
    border-top: 2px solid #000;
    border-bottom: 2px solid #000;
    font-weight:700;
  }

  .footer-note {
    font-size:13px;
    color:#000;
    text-align:center;
    margin-top:8px;
    font-family: Arial, sans-serif;
  }

  .item-name { color:#000; font-weight:500; }
  .item-desc { color:#000; }
  .item-description { white-space:normal; word-wrap:break-word; line-height:1.05; }

  .signature-table td {
    padding-top: 24px;
    font-size: 12px;
    vertical-align: top;
  }

  .signature-line {
    border-top: 1px solid #000;
    padding-top: 4px;
    margin-top: 28px;
  }
  </style>

  <div class="page-border"></div>

  <div class="heading-label">{{ heading_label }}</div>

  <!-- Supplier and order header -->
  <div class="section">
    <table class="info-table">
      <tr>
        <td style="width: 50%;">
          <strong>To:</strong><br>
          <strong>{{ doc.supplier }}</strong><br>
          {% if supplier_addr %}
            {{ supplier_addr[0].address_line1 or "" }}<br>
            {% if supplier_addr[0].address_line2 %}{{ supplier_addr[0].address_line2 }}<br>{% endif %}
            {{ supplier_addr[0].city or "" }}{% if supplier_addr[0].country %}, {{ supplier_addr[0].country }}{% endif %}<br>
          {% endif %}
        </td>
        <td class="rt" style="width: 50%;">
          Service Order No.: <strong>{{ doc.name }}</strong><br>
          Order Date: {{ frappe.utils.formatdate(doc.order_date, "dd-MMM-yy") }}<br>
          {% if doc.required_by_date %}Required By: {{ frappe.utils.formatdate(doc.required_by_date, "dd-MMM-yy") }}<br>{% endif %}
          Service Module: {{ doc.service_module or "-" }}<br>
          Currency: {{ doc.currency or "-" }}<br>
          Status: {{ doc.status or "-" }}
        </td>
      </tr>
    </table>
  </div>

  <!-- Scope of Work -->
  {% if doc.scope_of_work %}
  <div class="section">
    <div class="section-title">Scope of Work</div>
    <div style="font-size:12px; line-height:1.4;">{{ doc.scope_of_work }}</div>
    <hr style="border: none; border-top: 1px solid #000; margin-top: 8px; margin-bottom: 8px;">
  </div>
  {% endif %}

  <!-- Special Instructions -->
  {% if doc.special_instructions %}
  <div class="section">
    <div class="section-title">Special Instructions</div>
    <table class="info-table">
      <tr>
        <td style="font-size:12px; line-height:1.4; text-align:justify;">{{ doc.special_instructions }}</td>
      </tr>
    </table>
    <hr style="border: none; border-top: 1px solid #000; margin-top: 8px; margin-bottom: 8px;">
  </div>
  {% endif %}

  <!-- Charges -->
  <div class="section">
    <div class="section-title">Ordered Charges</div>
    <table class="items-table">
      <thead>
        <tr>
          <th class="cn" style="width:5%">#</th>
          <th style="width:20%">Charge</th>
          <th style="width:35%">Description</th>
          <th class="cn" style="width:10%">Qty</th>
          <th class="rt" style="width:15%">Rate</th>
          <th class="rt" style="width:15%">Amount</th>
        </tr>
      </thead>
      <tbody>
        {% for row in doc.service_order_charges %}
        <tr>
          <td class="cn">{{ loop.index }}</td>
          <td><span class="item-name">{{ row.charge }}</span></td>
          <td class="item-description"><span class="item-desc">{{ row.description or "" }}</span></td>
          <td class="cn">{{ row.qty or 1 }}</td>
          <td class="rt">{{ "{:,.2f}".format(row.buy_rate or 0) }}</td>
          <td class="rt">{{ "{:,.2f}".format(row.amount or 0) }}</td>
        </tr>
        {% endfor %}
      </tbody>
    </table>
  </div>

  <!-- Summary -->
  <div class="section">
    <div class="section-title">Summary</div>
    <table class="summary-table">
      <tr class="grand-total">
        <td style="width: 65%; border-top: 2px solid #000; border-bottom: 2px solid #000; padding-top: 4px; padding-bottom: 4px;"></td>
        <td style="width: 20%; border-top: 2px solid #000; border-bottom: 2px solid #000; padding-top: 4px; padding-bottom: 4px;"><strong>Total Amount</strong></td>
        <td class="rt" style="width: 15%; white-space: nowrap; border-top: 2px solid #000; border-bottom: 2px solid #000; padding-top: 4px; padding-bottom: 4px;"><strong>{{ doc.currency or "" }} {{ "{:,.2f}".format(doc.total_amount or 0) }}</strong></td>
      </tr>
    </table>
  </div>

  <!-- Terms and Conditions -->
  {% if doc.terms_and_conditions %}
  <div class="section">
    <div class="section-title">Terms &amp; Conditions</div>
    <table class="info-table">
      <tr>
        <td style="font-size: 12px; line-height: 1.4; text-align: justify;">{{ doc.terms_and_conditions|striptags|replace('\n', ' ')|replace('\r', ' ') }}</td>
      </tr>
    </table>
    <hr style="border: none; border-top: 1px solid #000; margin-top: 8px; margin-bottom: 8px;">
  </div>
  {% endif %}

  <!-- Signatures -->
  <div class="section">
    <table class="info-table signature-table">
      <tr>
        <td style="width: 50%;">
          <div class="signature-line">Prepared By: {{ prepared_by_name or doc.prepared_by or "________________" }}</div>
        </td>
        <td style="width: 50%;">
          <div class="signature-line">Authorized Signature</div>
        </td>
      </tr>
    </table>
  </div>

  <div class="footer-note">
    Please quote Service Order No. <strong>{{ doc.name }}</strong> on your invoice. Invoice exactly the total amount shown above; any additional charges must be submitted on a separate invoice.
  </div>
</div>
